mapper.insert:
insert into review_reports (review_id, member_id, reason, created_by,
updated_by)
values ( #{reviewId}, #{memberId}, #{reason}, #{createdBy}, #{updatedBy} );

mapper.update:
update review_reports
set reason = #{reason}, updated_by = #{updatedBy}
where id = #{id} and member_id = #{memberId} and delete_yn = 'N'

update review_reports
set delete_yn = 'Y', updated_by = #{updatedBy}
where id = #{id} and member_id = #{memberId} and delete_yn = 'N'

update review_reports
set status = #{status}, updated_by = #{updatedBy}
where id = #{id} and delete_yn = 'N'

update review_reports
set delete_yn = 'Y', updated_by = #{updatedBy}
where id = #{id} and delete_yn = 'N'

mapper.select:
SELECT reason_code, COUNT(*) AS report_count
FROM reports
GROUP BY reason_code;

SELECT member_id, COUNT(*) AS total_reports
FROM reports
GROUP BY member_id;

SELECT target_type, target_id, COUNT(*) AS report_count
FROM reports
GROUP BY target_type, target_id;
